using Dapper;
using DashBoard;
namespace DashBoard.Repositories;
public sealed class DashboardLayoutRepository
{
 private readonly SqlConnectionFactory _db;
 public DashboardLayoutRepository(SqlConnectionFactory db)=>_db=db;
 public async Task<dynamic?> GetUserLayoutAsync(int userId,string dashboardKey,string department,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="SELECT LayoutJson, UpdatedAt FROM dash.UserDashboardLayout WHERE UserId=@UserId AND DashboardKey=@DashboardKey AND DepartmentKey=@DepartmentKey;";return await db.QuerySingleOrDefaultAsync(new CommandDefinition(sql,new{UserId=userId,DashboardKey=dashboardKey,DepartmentKey=department},cancellationToken:ct));}
 public async Task<bool> SaveUserLayoutAsync(int userId,string dashboardKey,string department,string json,CancellationToken ct){await using var db=await _db.OpenAsync();const string check="SELECT COUNT(1) FROM dash.Dashboard WHERE DashboardKey=@DashboardKey AND DepartmentKey=@DepartmentKey AND IsActive=1;";if(await db.ExecuteScalarAsync<int>(new CommandDefinition(check,new{DashboardKey=dashboardKey,DepartmentKey=department},cancellationToken:ct))==0)return false;const string sql="UPDATE dash.UserDashboardLayout SET LayoutJson=@LayoutJson,UpdatedAt=SYSUTCDATETIME() WHERE UserId=@UserId AND DashboardKey=@DashboardKey AND DepartmentKey=@DepartmentKey; IF @@ROWCOUNT=0 INSERT INTO dash.UserDashboardLayout(UserId,DashboardKey,DepartmentKey,LayoutJson) VALUES(@UserId,@DashboardKey,@DepartmentKey,@LayoutJson);";await db.ExecuteAsync(new CommandDefinition(sql,new{UserId=userId,DashboardKey=dashboardKey,DepartmentKey=department,LayoutJson=json},cancellationToken:ct));return true;}
 public async Task<dynamic?> GetDepartmentLayoutAsync(string key,string department,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="SELECT LayoutJson,PublishedByUserId,PublishedAt,UpdatedAt FROM dash.DepartmentDashboardLayout WHERE DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey;";return await db.QuerySingleOrDefaultAsync(new CommandDefinition(sql,new{DepartmentKey=department,DashboardKey=key},cancellationToken:ct));}
 public async Task<bool> PublishDepartmentLayoutAsync(int userId,string key,string department,string json,CancellationToken ct){await using var db=await _db.OpenAsync();const string check="SELECT COUNT(1) FROM dash.Dashboard WHERE DashboardKey=@DashboardKey AND DepartmentKey=@DepartmentKey AND IsActive=1;";if(await db.ExecuteScalarAsync<int>(new CommandDefinition(check,new{DashboardKey=key,DepartmentKey=department},cancellationToken:ct))==0)return false;const string sql="UPDATE dash.DepartmentDashboardLayout SET LayoutJson=@LayoutJson,PublishedByUserId=@UserId,PublishedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey; IF @@ROWCOUNT=0 INSERT INTO dash.DepartmentDashboardLayout(DepartmentKey,DashboardKey,LayoutJson,PublishedByUserId) VALUES(@DepartmentKey,@DashboardKey,@LayoutJson,@UserId);";await db.ExecuteAsync(new CommandDefinition(sql,new{UserId=userId,DepartmentKey=department,DashboardKey=key,LayoutJson=json},cancellationToken:ct));return true;}
 public async Task DeleteDepartmentLayoutAsync(string key,string department,CancellationToken ct){await using var db=await _db.OpenAsync();await db.ExecuteAsync(new CommandDefinition("DELETE FROM dash.DepartmentDashboardLayout WHERE DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey;",new{DepartmentKey=department,DashboardKey=key},cancellationToken:ct));}
 public async Task<IEnumerable<dynamic>> GetDashboardPresetsAsync(string key,string department,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="SELECT PresetId,PresetName,Description,LayoutJson,CreatedAt,UpdatedAt FROM dash.DashboardLayoutPreset WHERE DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey AND IsActive=1 ORDER BY PresetName;";return await db.QueryAsync(new CommandDefinition(sql,new{DepartmentKey=department,DashboardKey=key},cancellationToken:ct));}
 public async Task<bool> DashboardExistsAsync(string key,string department,CancellationToken ct){await using var db=await _db.OpenAsync();return await db.ExecuteScalarAsync<int>(new CommandDefinition("SELECT COUNT(1) FROM dash.Dashboard WHERE DashboardKey=@DashboardKey AND DepartmentKey=@DepartmentKey AND IsActive=1;",new{DashboardKey=key,DepartmentKey=department},cancellationToken:ct))>0;}
 public async Task<int> CreateDashboardPresetAsync(string key,string department,string name,string? description,string json,int userId,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="INSERT INTO dash.DashboardLayoutPreset(DepartmentKey,DashboardKey,PresetName,Description,LayoutJson,CreatedByUserId) OUTPUT INSERTED.PresetId VALUES(@DepartmentKey,@DashboardKey,@PresetName,@Description,@LayoutJson,@UserId);";return await db.ExecuteScalarAsync<int>(new CommandDefinition(sql,new{DepartmentKey=department,DashboardKey=key,PresetName=name,Description=description,LayoutJson=json,UserId=userId},cancellationToken:ct));}
 public async Task<int> UpdateDashboardPresetAsync(string key,int id,string department,string name,string? description,string json,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="UPDATE dash.DashboardLayoutPreset SET PresetName=@PresetName,Description=@Description,LayoutJson=@LayoutJson,UpdatedAt=SYSUTCDATETIME() WHERE PresetId=@PresetId AND DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey AND IsActive=1;";return await db.ExecuteAsync(new CommandDefinition(sql,new{PresetId=id,DepartmentKey=department,DashboardKey=key,PresetName=name,Description=description,LayoutJson=json},cancellationToken:ct));}
 public async Task<int> DeleteDashboardPresetAsync(string key,int id,string department,CancellationToken ct){await using var db=await _db.OpenAsync();const string sql="DELETE FROM dash.DashboardLayoutPreset WHERE PresetId=@PresetId AND DepartmentKey=@DepartmentKey AND DashboardKey=@DashboardKey;";return await db.ExecuteAsync(new CommandDefinition(sql,new{PresetId=id,DepartmentKey=department,DashboardKey=key},cancellationToken:ct));}
}